parameters.jsCode:
// Console outbound payload (backend outbound.py):
// { review_item_id, image_base64, qb_invoice, submitted_by, secret }
const b = $('Console Trigger').item.json.body || {};
const qb = String(b.qb_invoice == null ? '' : b.qb_invoice).trim();
const submitted = String(b.submitted_by || '').trim();
const local = submitted.split('@')[0] || '';
return { json: {
  review_item_id: String(b.review_item_id || ''),
  image_base64: String(b.image_base64 || ''),
  qb_invoice: qb || null,
  submitted_by: submitted || null,
  submitted_by_name: local ? (local.charAt(0).toUpperCase() + local.slice(1)) : 'a manager',
  // Synthesized caption: keeps the transplanted OCR prompt + parser working
  // exactly as in production (caption_invoice, cash_invoice fall out of it).
  caption: qb ? ('invoice ' + qb) : ''
}};

// ===== Hardened check reader (Parse Check Data) =====

// 1) Pull the JSON object out of the model reply
const rawText = $input.item.json.content[0].text || '';
let jsonStr = rawText.replace(/```json|```/g, '').trim();
const f = jsonStr.indexOf('{'), l = jsonStr.lastIndexOf('}');
if (f !== -1 && l !== -1) jsonStr = jsonStr.slice(f, l + 1);
let check = {};
try { check = JSON.parse(jsonStr); } catch (e) { check = {}; }

function cleanText(v){ if(v===undefined||v===null) return null; const t=String(v).replace(/\s+/g,' ').trim(); return t.length?t:null; }
function digitsOnly(v){ if(v===undefined||v===null) return null; const dd=String(v).replace(/[^0-9]/g,''); return dd.length?dd:null; }
function toMoney(v){ if(v===undefined||v===null) return null; const n=parseFloat(String(v).replace(/[^0-9.]/g,'')); return isNaN(n)?null:Math.round(n*100)/100; }

// 2) CHECK NUMBER — vote across corner + MICR + MICR tail + model's value
const cnCorner = digitsOnly(check.check_number_corner);
const cnMicr   = digitsOnly(check.check_number_micr);
let   cnTail   = null;
if (check.micr_line_raw){ const g=String(check.micr_line_raw).split(/[^0-9]+/).filter(x=>x.length); if(g.length) cnTail=g[g.length-1]; }
const cnModel  = digitsOnly(check.check_number);
const cnVotes  = [cnCorner,cnMicr,cnTail,cnModel].filter(x=>x!==null);
let check_number = cnModel||cnMicr||cnCorner||cnTail||null, check_number_verified=false;
if (cnVotes.length){
  const t={}; for(const v of cnVotes) t[v]=(t[v]||0)+1;
  const r=Object.entries(t).sort((a,b)=>b[1]-a[1]);
  check_number=r[0][0];
  check_number_verified=(r[0][1]>=2) && (String(check.check_number_confidence||'').toLowerCase()==='high');
}

// 3) AMOUNT — courtesy vs legal; on conflict the WRITTEN amount wins
const amtC=toMoney(check.amount_numeric), amtL=toMoney(check.amount_written);
const amtHigh=String(check.amount_confidence||'').toLowerCase()==='high';
let amount=null, amount_verified=false, amount_conflict=false;
if (amtC!==null && amtL!==null){
  if (amtC===amtL){ amount=amtC; amount_verified=amtHigh; }
  else { amount=amtL; amount_conflict=true; amount_verified=false; }
} else { amount=(amtL!==null)?amtL:amtC; amount_verified=false; }

// 4) CAPTION — split payment-hint words from a real customer name
const rawCaption = cleanText($('Trigger Context').item.json.caption) || '';
const captionRaw = cleanText(check.caption_name) || rawCaption;

// hint can come from the caption OR Claude's read of the memo line
function hintFrom(s){
  s = (s||'').toString().toLowerCase();
  if (/\b(pif|payoff|paid in full|full)\b/.test(s)) return 'PIF';
  if (/\b(deposit|dep|down)\b/.test(s)) return 'deposit';
  if (/\b(remainder|remaining|remain|rem|balance|bal|final)\b/.test(s)) return 'remainder';
  if (/\b(progress|prog|partial)\b/.test(s)) return 'progress';
  return null;
}
let paymentHint = hintFrom(rawCaption) || hintFrom(captionRaw) || hintFrom(check.payment_hint);

// strip payment/admin words; whatever real name remains (if any) is the customer
function stripHintWords(s){
  return (s||'').toString()
    .replace(/\b(pif|payoff|pay off|paid in full|paid|pays|pay|payment|pmt|full|deposit|dep|down payment|downpayment|down|remainder|remaining|remain|rem|balance|bal|final|progress|prog|partial|check|cheque|ck|chk|invoice|inv|job|for|from|the)\b/gi,' ')
    .replace(/#?\d+/g,' ')
    .replace(/[^A-Za-z\s'.\-]/g,' ')
    .replace(/\s+/g,' ').trim();
}
let captionName = null, usedCaption = false;
if (captionRaw){
  const namePart = stripHintWords(captionRaw);
  if (namePart.replace(/[^A-Za-z]/g,'').length >= 2) captionName = namePart;
}

// 5) NAME PARTS — a real caption name wins; else use the check's printed name (address always travels too)
const checkName = cleanText(check.payer_name);
const chkFirst = cleanText(check.first_name);
const chkMid   = cleanText(check.middle_name);
const chkLast  = cleanText(check.last_name);
let first_name=null, middle_name=null, last_name=null;
if (captionName){
  const parts = captionName.split(/\s+/).filter(Boolean);
  if (parts.length>=2){ first_name=parts[0]; last_name=parts[parts.length-1]; }
  else { last_name=captionName; }
  usedCaption=true;
} else {
  first_name=chkFirst; middle_name=chkMid; last_name=chkLast;
}

// 6) entity type + address (always from the check)
let entity_type = (check.entity_type||'').toString().toLowerCase()==='business' ? 'business' : 'individual';
const street_number = cleanText(check.street_number);
const street_name   = cleanText(check.street_name);
const zip           = cleanText(check.zip);
const display_name = captionName || checkName || ([first_name,last_name].filter(Boolean).join(' ')) || null;

// caption may carry an invoice number ("6465 rem") - capture it as an invoice #, never a name
const captionInvoice = ((rawCaption||'').match(/\d{3,}/) || [null])[0];

// every printed name becomes a search candidate so the surname is tried no matter how the lines parse
let additional_names = [];
if (Array.isArray(check.all_payer_names)) additional_names = check.all_payer_names.map(cleanText).filter(x => x && x.replace(/[^A-Za-z]/g,'').length >= 2);
if (checkName && !additional_names.some(n => n.toLowerCase() === checkName.toLowerCase())) additional_names.push(checkName);
if (last_name && !additional_names.some(n => n.toLowerCase() === last_name.toLowerCase())) additional_names.push(last_name);
additional_names = Array.from(new Set(additional_names));

// 7) confidence flags
const flags=[];
if(!check_number_verified) flags.push('check# needs review');
if(amount_conflict) flags.push('AMOUNT MISMATCH: $'+amtC+' figures vs $'+amtL+' words - using words');
else if(!amount_verified) flags.push('amount needs review');

// 8) need a name OR an address to search
if(!last_name && !street_number){
  return { json: { readable:false, message:"Couldn't read a usable name or address from the check or caption." } };
}

return { json: {
  readable:true,
  check_number, check_number_verified,
  display_name, payer_name: checkName || display_name,
  caption_name: captionName, used_caption: usedCaption,
  caption_job_name: cleanText(check.caption_name),
  first_name, middle_name, last_name, entity_type,
  street_number, street_name, zip,
  payment_hint: paymentHint,
  caption_invoice: captionInvoice,
  document_type: (cleanText(check.document_type)||'').toLowerCase(),
  cash_amount: (check.cash_amount!=null && /[0-9]/.test(String(check.cash_amount))) ? parseFloat(String(check.cash_amount).replace(/[^0-9.]/g,'')) : null,
  cash_invoice: (check.cash_invoice!=null && /[0-9]/.test(String(check.cash_invoice))) ? String(check.cash_invoice).replace(/[^0-9]/g,'') : null,
  additional_names: additional_names,
  amount, amount_verified, amount_conflict,
  amount_numeric: amtC, amount_written: amtL,
  date: check.date || null,
  confidence_flags: flags.join('; ')
}};

