const p=Object.assign({},$('Parse Check Data').item.json,$('Cash Data').item.json);
const job=$('Cash Job By Invoice').item.json;
const wh={body:{data:{key:{id:$('Trigger Context').item.json.review_item_id,remoteJid:'console'}}}};
function fmt(v){const n=parseFloat(String(v==null?'':v).replace(/[^0-9.\-]/g,''));if(isNaN(n))return '?';let q=(Math.round(n*100)/100).toFixed(2).split('.');q[0]=q[0].replace(/\B(?=(\d{3})+(?!\d))/g,',');return q[0]+'.'+q[1];}
const amount=p.cash_amount;
const inv=String(p.cash_invoice||'');
const ptype=(p.payment_hint||'unknown').toString();
const typeLabel=ptype==='PIF'?'paid in full':(ptype==='unknown'?'payment':ptype);
const jobName=job.CustomerName||'';
const jobId=job.JobId;
const leadUrl=job.LeadUrl||'';
const amtStr='$'+fmt(amount);
const notes='Cash payment received \u2014 '+(jobName||'customer')+' paid '+amtStr+' ('+typeLabel+') \u2014 invoice #'+inv+'. Logged automatically by check-bot (cash, matched by invoice).';
const msg='\ud83d\udcb5 *Cash recorded*\n\n'+amtStr+' \u00b7 '+typeLabel+'\nInvoice #'+inv+'\nJob: *'+(jobName||'(unknown)')+'*'+(leadUrl?('\n'+leadUrl):'')+'\n\n\u2705 Recorded in the console\n\u2705 Logged to the Moraware job\nMatched by invoice \u2014 no action needed.';
return { json: {
  Status:'confirmed', CheckNumber:'', PayerName:(p.caption_name||p.payer_name||'Cash'), CaptionName:p.caption_name,
  Amount:amount, PaymentType:ptype, PaymentMethod:'Cash',
  JobName:jobName, JobId:jobId, MorawareURL:leadUrl, InvoiceNumber:inv, MatchMethod:'cash-invoice:'+(job.Source||''),
  MessageId:wh.body.data.key.id, GroupJID:wh.body.data.key.remoteJid, ConfidenceFlags:'cash',
  jobId:jobId, noteText:notes, remoteJid:wh.body.data.key.remoteJid, messageId:wh.body.data.key.id, messageText:msg
}};

