// Pull the invoice off the QB response and list its linked PAYMENT txn ids.
const resp = ($json && $json.QueryResponse) || {};
const inv = (resp.Invoice && resp.Invoice[0]) || null;
let ids = [];
if (inv && Array.isArray(inv.LinkedTxn)) {
  ids = inv.LinkedTxn
    .filter(t => t && t.TxnType === 'Payment' && t.TxnId)
    .map(t => String(t.TxnId));
}
const idClause = ids.length
  ? ('Id IN (' + ids.map(i => "'" + i + "'").join(',') + ')')
  : "Id = '0'";
return { json: { idClause: idClause, linkedPaymentIds: ids } };

const p=$('Parse Check Data').item.json;
const job=$('Photo Job By Invoice').item.json;
const wh={body:{data:{key:{id:$('Trigger Context').item.json.review_item_id,remoteJid:'console'}}}};
function fmt(v){const n=parseFloat(String(v==null?'':v).replace(/[^0-9.\-]/g,''));if(isNaN(n))return '?';let q=(Math.round(n*100)/100).toFixed(2).split('.');q[0]=q[0].replace(/\B(?=(\d{3})+(?!\d))/g,',');return q[0]+'.'+q[1];}
const num=v=>{const n=parseFloat(String(v==null?'':v).replace(/[^0-9.\-]/g,''));return isNaN(n)?null:n;};
function money(n){return n==null?'$?':('$'+fmt(n));}
const EPS=0.005;
const inv=p.caption_invoice||''; const hintType=(p.payment_hint||'unknown').toString();
const jobName=job.CustomerName||''; const jobId=job.JobId; const leadUrl=job.LeadUrl||''; const amtStr='$'+fmt(p.amount);

// ----- QB already-recorded detection (same rule as Classify Payment) -----
let qbInv=null;
try{ qbInv=$('AC Get QB Invoice').item.json.QueryResponse.Invoice[0]||null; }catch(e){ qbInv=null; }
const qbReachable=qbInv!==null;
const T=qbInv?num(qbInv.TotalAmt):null;
const B=qbInv?num(qbInv.Balance):null;
let pays=[];
try{ const arr=$('AC Get QB Payments').item.json.QueryResponse.Payment; if(Array.isArray(arr)) pays=arr.map(x=>({refNum:String(x.PaymentRefNum==null?'':x.PaymentRefNum).trim(),amt:num(x.TotalAmt)})); }catch(e){ pays=[]; }
const checkNum=String(p.check_number==null?'':p.check_number).trim();
const A=num(p.amount);
const matched=pays.find(x=>x.refNum && x.refNum===checkNum);
const inQB=!!matched;
const owedNow=(B!==null)?B:null;

// ----- classify from QB when the caption gave no hint (same F-based rule as Classify Payment) -----
function fullContract(invObj){
  if(!invObj||!Array.isArray(invObj.Line)) return null;
  let s=0, frac=false;
  for(const ln of invObj.Line){
    const dt=String((ln&&ln.DetailType)||'');
    if(dt==='DiscountLineDetail'&&ln.Amount!=null){ s-=Number(ln.Amount)||0; continue; }
    const dd=ln&&ln.SalesItemLineDetail;
    if(dt!=='SalesItemLineDetail'||!dd) continue;
    const qty=(dd.Qty!=null)?Number(dd.Qty):null;
    const unit=(dd.UnitPrice!=null)?Number(dd.UnitPrice):null;
    const a=(ln.Amount!=null)?Number(ln.Amount):0;
    const nm=String(((dd.ItemRef&&dd.ItemRef.name)||'')+' '+(ln.Description||''));
    const feeName=/credit\s*card|credit\s*c\s*%|cc\s*fee|card\s*fee|surcharge|processing\s*fee|convenience\s*fee/i.test(nm);
    const feeQty=(qty!=null&&qty>0&&qty<0.2);
    if(feeName||feeQty) continue; // payment-method fees are not part of the contract
    if(qty!=null&&qty>0&&qty<1&&unit!=null&&unit>0){ s+=unit; frac=true; }
    else s+=a;
  }
  if(!frac) return null;
  return Math.round(s*100)/100;
}
let qbType=null;
if(T!==null&&B!==null&&A!==null){
  const F0=fullContract(qbInv);
  const F=(F0!=null)?Math.max(F0,T):T; // full contract (Rate x 1); = TotalAmt when no fractional-qty lines
  const paidSoFar=T-B;
  let priorPaid=inQB?(paidSoFar-(A||0)):paidSoFar;
  if(priorPaid<EPS) priorPaid=0;
  const cumAfter=priorPaid+A;
  if(cumAfter>=F-EPS) qbType=priorPaid>EPS?'remainder':'PIF';
  else qbType=priorPaid>EPS?'progress':'deposit';
}
const ptype=qbType||((hintType!=='unknown')?hintType:'unknown');
const typeLabel=ptype==='PIF'?'paid in full':(ptype==='unknown'?'payment':(ptype==='progress'?'progress payment':ptype));

let qbLine;
if(inQB){
  qbLine=(owedNow!==null && owedNow<=EPS)
    ? '\u2705 Already in QuickBooks \u00b7 invoice paid in full'
    : (owedNow!==null ? '\u2705 Already in QuickBooks \u00b7 '+money(owedNow)+' still owing' : '\u2705 Already in QuickBooks');
}else if(qbReachable && owedNow!==null){
  const after=Math.max(0,owedNow-(A||0));
  qbLine=(after<=EPS)
    ? '\u23f3 *Not yet in QuickBooks* \u2014 please enter this payment (QuickBooks still shows '+money(owedNow)+' owing; entering it pays the invoice in full)'
    : '\u23f3 *Not yet in QuickBooks* \u2014 please enter this payment (after you do, '+money(after)+' will remain)';
}else{
  qbLine='\u23f3 *Not yet in QuickBooks* \u2014 please enter this payment when you can';
}
const closing = inQB
  ? 'Matched by invoice \u2014 recorded in the console and noted on the job. No action needed.'
  : 'Matched by invoice \u2014 recorded in the console and noted on the job.';

const notes='Payment received \u2014 '+(jobName||'customer')+' paid '+amtStr+' ('+typeLabel+') \u2014 by Check'+(inv?(' \u00b7 invoice #'+inv):'')+'. Logged automatically by check-bot (matched by invoice).';
const msg='\u2705 *Updated \u2014 check recorded*\n\nCheck #'+(p.check_number||'?')+' \u00b7 '+amtStr+' \u00b7 '+typeLabel+'\nInvoice #'+(inv||'?')+'\nJob: *'+(jobName||'(unknown)')+'*'+(leadUrl?('\n'+leadUrl):'')+'\n\n'+qbLine+'\n'+closing;
return { json: {
  Status:'confirmed', CheckNumber:p.check_number, PayerName:p.payer_name, CaptionName:p.caption_name,
  Amount:p.amount, PaymentType:ptype, PaymentMethod:'Check',
  JobName:jobName, JobId:jobId, MorawareURL:leadUrl, InvoiceNumber:inv, MatchMethod:'invoice:'+(job.Source||''),
  MessageId:wh.body.data.key.id, GroupJID:wh.body.data.key.remoteJid, ConfidenceFlags:p.confidence_flags,
  jobId:jobId, noteText:notes, remoteJid:wh.body.data.key.remoteJid, messageId:wh.body.data.key.id, messageText:msg,
  inQB:inQB, qbReachable:qbReachable
}};

