// AV Merge Fanout - union smart-search matches with 2-word name matches, one item per candidate job
const seed = $('AV Seed').first().json;
let fb = {};
try { fb = $input.first().json || {}; } catch (e) { fb = {}; }
const primary = Array.isArray(seed.Matches) ? seed.Matches : [];
const fallback = (fb && Array.isArray(fb.Matches)) ? fb.Matches : [];
const seen = new Set(); const cands = [];
for (const m of primary.concat(fallback)) {
  if (!m || !m.JobId || seen.has(m.JobId)) continue;
  seen.add(m.JobId);
  cands.push({ JobId: m.JobId, CustomerName: m.CustomerName || '', LeadUrl: m.LeadUrl || '',
               NameMatchStrength: m.NameMatchStrength || 'weak', CreationDate: m.CreationDate || null,
               AddressLine2: m.AddressLine2 || null });
  if (cands.length >= 4) break;
}
if (!cands.length) return [{ json: { _empty: true, JobId: 0, _amount: seed._amount } }];
return cands.map((c, i) => ({ json: Object.assign({ _idx: i, _amount: seed._amount, _empty: false }, c) }));

