// AV Build QB Query - one QB query per candidate covering ALL its Moraware invoice numbers
const inv = $json || {};
let nums = Array.isArray(inv.InvoiceNumbers) ? inv.InvoiceNumbers : [];
nums = nums.map(x => String(x || '').replace(/[^0-9]/g, '')).filter(x => x.length >= 3 && x.length <= 6);
nums = Array.from(new Set(nums)).slice(0, 15);
const cand = $('AV Merge Fanout').item.json;
const list = nums.length ? nums.map(n => "'" + n + "'").join(',') : "'__none__'";
const q = 'SELECT * FROM Invoice WHERE DocNumber IN (' + list + ')';
return { json: Object.assign({}, cand, { _invNums: nums,
  _qbUrl: ($('Pilot Config').first().json.qb_company_url + '/query?query=') + q + '&minorversion=65' }) };

// AV Collector - score the check amount against every invoice of every candidate
const fan = $('AV Merge Fanout').all();
const qb = $input.all();
const seed = $('AV Seed').first().json;
const orig = Object.assign({}, seed); delete orig._first2; delete orig._amount;
const amt = (seed._amount != null) ? Number(seed._amount) : null;

function invoicesFrom(j) { try { const a = j.QueryResponse && j.QueryResponse.Invoice; return Array.isArray(a) ? a : []; } catch (e) { return []; } }

const hits = [];
if (amt != null && !isNaN(amt)) {
  for (let i = 0; i < fan.length; i++) {
    const cand = fan[i].json; if (cand._empty) continue;
    const invs = invoicesFrom((qb[i] && qb[i].json) || {});
    let best = null;
    for (const v of invs) {
      const T = (v.TotalAmt != null) ? Number(v.TotalAmt) : null;
      const B = (v.Balance != null) ? Number(v.Balance) : null;
      let kind = null;
      if (T != null && Math.abs(amt - T) <= 0.005) kind = 'full';
      else if (B != null && B > 0.005 && Math.abs(amt - B) <= 0.005) kind = 'remainder';
      else if (T != null && Math.abs(amt - 0.75 * T) <= 1.00) kind = 'deposit';
      if (!kind) continue;
      const rank = { full: 3, remainder: 2, deposit: 1 }[kind];
      if (!best || rank > best.rank) best = { rank, kind, doc: String(v.DocNumber || ''), T, B };
    }
    if (best) hits.push({ cand, inv: best.doc, kind: best.kind, T: best.T, B: best.B });
  }
}

if (hits.length === 1) {
  const h = hits[0];
  const m = Object.assign({}, h.cand); m.NameMatchStrength = 'strong';
  delete m._idx; delete m._amount; delete m._empty;
  return [{ json: {
    Matches: [m], MatchedStrategy: 'amount:' + h.kind, Ambiguous: false,
    _amountInvoice: h.inv, _amountKind: h.kind, _amountTotal: h.T, _amountBalance: h.B,
    _skipped_note: seed._skipped_note || ''
  } }];
}
if (hits.length > 1) {
  const ms = hits.map(h => { const m = Object.assign({}, h.cand); m.NameMatchStrength = 'weak';
    m._hitInvoice = h.inv; m._hitKind = h.kind; delete m._idx; delete m._amount; delete m._empty; return m; });
  return [{ json: { Matches: ms, MatchedStrategy: 'amount-multi', Ambiguous: true, _skipped_note: seed._skipped_note || '' } }];
}
const origMatches = Array.isArray(orig.Matches) ? orig.Matches : [];
if (origMatches.length) return [{ json: orig }];
const fbCands = fan.filter(f => !f.json._empty).map(f => { const m = Object.assign({}, f.json);
  m.NameMatchStrength = m.NameMatchStrength || 'weak'; delete m._idx; delete m._amount; delete m._empty; return m; });
if (fbCands.length) return [{ json: { Matches: fbCands, MatchedStrategy: 'name2words', Ambiguous: fbCands.length > 1, _skipped_note: orig._skipped_note || '' } }];
return [{ json: orig }];

const r=$input.item.json;
const matches=Array.isArray(r.Matches)?r.Matches:[];
const strategy=r.MatchedStrategy||'none';
const ambiguous=!!r.Ambiguous;
const addressAmbiguous=(strategy==='address'&&ambiguous&&matches.length>1);
function pick(list){return list.length?list[0]:null;}
let chosen=null;
if(matches.length&&!addressAmbiguous){
  const strong=matches.filter(m=>m.NameMatchStrength==='strong');
  chosen=strong.length?pick(strong):pick(matches);
}
let shortName='';
if(chosen&&chosen.CustomerName){
  const tok=String(chosen.CustomerName).replace(/[^A-Za-z0-9 ]+/g,' ').trim().split(/\s+/)[0]||'';
  if(tok.length>=3) shortName=tok;
}
const dontVet = !!r._amountInvoice || !!r.Ambiguous || String(r.MatchedStrategy||'').indexOf('amount')===0;
return { json: Object.assign({}, r, { _cand: chosen, _hasCand: !!(chosen&&chosen.JobId) && !dontVet, _shortName: shortName }) };

