function fullContract(invObj){
  if(!invObj||!Array.isArray(invObj.Line)) return null;
  let s=0, frac=false;
  for(const ln of invObj.Line){
    const dt=String((ln&&ln.DetailType)||'');
    if(dt==='DiscountLineDetail'&&ln.Amount!=null){ s-=Number(ln.Amount)||0; continue; }
    const dd=ln&&ln.SalesItemLineDetail;
    if(dt!=='SalesItemLineDetail'||!dd) continue;
    const qty=(dd.Qty!=null)?Number(dd.Qty):null;
    const unit=(dd.UnitPrice!=null)?Number(dd.UnitPrice):null;
    const a=(ln.Amount!=null)?Number(ln.Amount):0;
    const nm=String(((dd.ItemRef&&dd.ItemRef.name)||'')+' '+(ln.Description||''));
    const feeName=/credit\s*card|credit\s*c\s*%|cc\s*fee|card\s*fee|surcharge|processing\s*fee|convenience\s*fee/i.test(nm);
    const feeQty=(qty!=null&&qty>0&&qty<0.2);
    if(feeName||feeQty) continue; // payment-method fees are not part of the contract
    if(qty!=null&&qty>0&&qty<1&&unit!=null&&unit>0){ s+=unit; frac=true; }
    else s+=a;
  }
  if(!frac) return null;
  return Math.round(s*100)/100;
}
const raw=$('Vet Prep').item.json;
