const B=(qbInv&&qbInv.Balance!=null)?Number(qbInv.Balance):null;
const F0=fullContract(qbInv);
const F=(F0!=null&&T!=null)?Math.max(F0,T):((F0!=null)?F0:T);
const contractOpen=(F!=null&&T!=null&&F>T+0.005);
const paidInFull=(qbInv!==null&&moraInv!==''&&B!==null&&B<=0.005&&!contractOpen);
return { json: Object.assign({}, raw, { _skip: paidInFull, _skipInv: paidInFull?moraInv:'', _skipJobId: raw._cand?raw._cand.JobId:null, _skipJobName: raw._cand?(raw._cand.CustomerName||''):'' }) };

