  const inv = m._hitInvoice ? (' \u2014 Invoice #'+m._hitInvoice+(m._hitKind?(' ('+m._hitKind+')'):'')) : '';
  return `${i+1}. ${m.CustomerName}${unit}${inv}\n   ${m.LeadUrl}`;
}).join('\n');
return { json: { units_text: lines, count: list.length, header_text: header } };

