function money(n){
  if (n === null || n === undefined || n === '' || isNaN(Number(n))) return '$?';
  let v = Math.round(Number(n) * 100) / 100;
  let p = v.toFixed(2).split('.');
  p[0] = p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return '$' + p[0] + '.' + p[1];
}
function canon(t){
  t = (t||'').toString().trim().toLowerCase();
  if (t==='deposit') return 'deposit';
  if (t==='remainder') return 'remainder';
  if (t==='pif' || t==='paid in full') return 'PIF';
  if (t==='progress') return 'progress';
  return 'unknown';
}
function label(c){
  if (c==='deposit') return 'deposit';
  if (c==='remainder') return 'remainder';
  if (c==='PIF') return 'paid in full';
  if (c==='progress') return 'progress payment';
  return 'payment type pending verification';
}

