const A = num(row.Amount);
const captionHint = (row.PaymentType || '').toString().trim().toLowerCase();
const rawName = (row.JobName || row.PayerName || 'Unknown payer').toString().trim();
const payerName = rawName.replace(/\s*\([^)]*\)\s*$/, '').trim() || rawName;
const MORA_BASE='https://granite-marble-tops.moraware.net/sys/job/';
const mmRaw=String(row.MatchMethod||'');
let candJobId=null, candJobName='', candUrl='', mmClean=mmRaw;
if(mmRaw.indexOf('pending-fallback~~')===0){ const pp=mmRaw.split('~~'); candJobId=pp[1]?Number(pp[1]):null; candJobName=pp[2]||''; candUrl=pp[3]||''; mmClean='fallback:'+(pp[4]||''); }
const rowJobIdN=(row.JobId!==undefined&&row.JobId!==null&&String(row.JobId).trim()!=='')?Number(row.JobId):null;
const effJobId=(rowJobIdN!==null&&!isNaN(rowJobIdN))?rowJobIdN:candJobId;
const jobName=(String(row.JobName||'').trim())||candJobName||payerName;
const effUrl=(String(row.MorawareURL||'').trim())||candUrl||(effJobId?(MORA_BASE+effJobId):'');
const invoiceNum = (row.InvoiceNumber || '').toString().trim() || 'pending';

// QB invoice figures
function fullContract(invObj){
  if(!invObj||!Array.isArray(invObj.Line)) return null;
  let s=0, frac=false;
  for(const ln of invObj.Line){
    const dt=String((ln&&ln.DetailType)||'');
    if(dt==='DiscountLineDetail'&&ln.Amount!=null){ s-=Number(ln.Amount)||0; continue; }
    const dd=ln&&ln.SalesItemLineDetail;
    if(dt!=='SalesItemLineDetail'||!dd) continue;
    const qty=(dd.Qty!=null)?Number(dd.Qty):null;
    const unit=(dd.UnitPrice!=null)?Number(dd.UnitPrice):null;
    const a=(ln.Amount!=null)?Number(ln.Amount):0;
    const nm=String(((dd.ItemRef&&dd.ItemRef.name)||'')+' '+(ln.Description||''));
    const feeName=/credit\s*card|credit\s*c\s*%|cc\s*fee|card\s*fee|surcharge|processing\s*fee|convenience\s*fee/i.test(nm);
    const feeQty=(qty!=null&&qty>0&&qty<0.2);
    if(feeName||feeQty) continue; // payment-method fees are not part of the contract
    if(qty!=null&&qty>0&&qty<1&&unit!=null&&unit>0){ s+=unit; frac=true; }
    else s+=a;
  }
  if(!frac) return null;
  return Math.round(s*100)/100;
}
let inv = null;
try { inv = $('Get QB Invoice').item.json.QueryResponse.Invoice[0] || null; } catch(e) { inv = null; }
const qbReachable = inv !== null;
const T = inv ? num(inv.TotalAmt) : null;
const B = inv ? num(inv.Balance) : null;
const F0 = fullContract(inv);
const F = (F0 != null && T != null) ? Math.max(F0, T) : ((F0 != null) ? F0 : T); // full contract; equals TotalAmt when no fractional-qty lines
const fracInv = (F != null && T != null && F > T + EPS);


// QB payments linked to the invoice
let pays = [];
try {
  const arr = $json.QueryResponse.Payment;
  if (Array.isArray(arr)) pays = arr.map(p => ({
    id: String(p.Id ?? '').trim(),
    refNum: String(p.PaymentRefNum ?? '').trim(),
    amt: num(p.TotalAmt),
    date: String(p.TxnDate ?? '').slice(0,10)
  }));
} catch(e) { pays = []; }

const qbPid = String(row.QBPaymentId ?? '').trim();
const matched = (qbPid ? pays.find(p => p.id && p.id === qbPid) : null) || pays.find(p => p.refNum && p.refNum === checkNumber);
const inQB = !!matched;
// Prior payments = what QuickBooks already shows paid on this invoice, anchored to the
// invoice Balance (authoritative, date-independent). If this check is itself already
// recorded in QB, its amount is part of that figure, so subtract it for the BEFORE state.
let priorPaid = null;
let beforeBalance = null;
if (T !== null && B !== null) {
  const paidSoFar = T - B;
  priorPaid = inQB ? (paidSoFar - (A || 0)) : paidSoFar;
  if (priorPaid < EPS) priorPaid = 0;
  beforeBalance = T - priorPaid;
} else if (T !== null) {
  let sum = 0;
  for (const p of pays) { if (p.refNum && p.refNum === checkNumber) continue; sum += (p.amt || 0); }
  priorPaid = sum;
  beforeBalance = T - priorPaid;
}

// ----- classify -----
const flags = [];
let qbType = null;
if (T === null || A === null || beforeBalance === null) {
  flags.push('QB invoice unavailable - could not auto-classify');
} else {
  const cumAfter = (priorPaid || 0) + A;               // collected toward the contract incl. this check
  const contractLeft = (F !== null) ? (F - cumAfter) : null; // measured vs the FULL contract (Rate x 1), not the qty-discounted invoice total
  if (contractLeft !== null && contractLeft <= EPS) {
    qbType = priorPaid > EPS ? 'remainder' : 'PIF';
  } else {
    qbType = priorPaid > EPS ? 'progress' : 'deposit';
  }
  if (beforeBalance <= EPS && !fracInv) flags.push('QB shows nothing owed before this check - verify invoice total (possible scope increase)');
  if ((A - beforeBalance) > EPS && !(fracInv && cumAfter <= F + EPS)) flags.push('check amount is more than the invoice balance - possible scope increase, verify');
}

// ----- QB balance block: anchored to what QuickBooks ACTUALLY shows right now -----
const owedNow = (B !== null) ? B : beforeBalance; // current amount QuickBooks shows owing
let qbBalanceBlock;
if (!qbReachable || owedNow === null) {
  qbBalanceBlock = "\u26a0 Couldn't reach QuickBooks to check the balance";
} else if (inQB) {
  qbBalanceBlock = (owedNow <= EPS)
    ? '\u2713 Already recorded in QuickBooks \u00b7 invoice paid in full'
    : '\u2713 Already recorded in QuickBooks \u00b7 ' + money(owedNow) + ' still owing';
} else {
  const after = Math.max(0, owedNow - (A || 0));
  const head = '\u23f3 Not yet recorded in QuickBooks (it still shows ' + money(owedNow) + ' owing)';
  qbBalanceBlock = (after <= EPS)
    ? head + '\nEntering this check will pay the invoice in full'
    : head + '\nAfter you enter it, ' + money(after) + ' will remain';
}
if (fracInv && priorPaid !== null && A !== null) {
  const collectedNow = (priorPaid || 0) + A;
  qbBalanceBlock += '\n\u2139 75%-style invoice \u00b7 full contract ' + money(F) + ' \u00b7 collected ' + money(collectedNow);
}


// ----- QuickBooks is the truth; the caption hint only fills gaps -----
const hint = (captionHint && captionHint !== 'unknown') ? canon(captionHint) : null;
let paymentType;
if (qbType) {
  paymentType = canon(qbType);
  if (hint && hint !== 'unknown' && hint !== qbType) flags.push("the check/caption said '" + hint + "' but QuickBooks shows a '" + qbType + "' - using QuickBooks");
} else if (hint && hint !== 'unknown') {
  paymentType = hint;
} else {
  paymentType = 'unknown';
}

// ----- human-readable context for the note + confirmation -----
const remainingAfterNum = (beforeBalance !== null && A !== null) ? (beforeBalance - A) : null;
const priorPaidStr = (priorPaid !== null && priorPaid > EPS) ? money(priorPaid) : null;
const remainingAfterStr = (remainingAfterNum !== null) ? money(Math.max(0, remainingAfterNum)) : null;
let paymentContext = '';
if (priorPaidStr) {
  paymentContext = (remainingAfterNum !== null && remainingAfterNum <= EPS)
    ? (priorPaidStr + ' previously paid \u00b7 pays the invoice in full')
    : (remainingAfterStr ? (priorPaidStr + ' previously paid \u00b7 ' + remainingAfterStr + ' remaining') : (priorPaidStr + ' previously paid'));
}

return { json: {
  paymentType: paymentType,
  typeLabel: label(paymentType),
  payerName: payerName,
  jobName: jobName,
  leadUrl: effUrl,
  matchMethodClean: mmClean,
  invoiceNum: invoiceNum,
  amountStr: money(A),
  amountNum: A,
  checkNumber: checkNumber || '?',
  jobId: effJobId,
  source: qbType ? 'quickbooks' : 'caption',
  inQB: inQB,
  qbReachable: qbReachable,
  qbType: qbType || null,
  invoiceTotal: T,
  invoiceBalance: B,
  beforeBalance: beforeBalance,
  priorPaid: priorPaid,
  priorPaidStr: priorPaidStr,
  remainingAfter: remainingAfterNum,
  paymentContext: paymentContext,
  qbBalanceBlock: qbBalanceBlock,
  classifierFlags: flags.join('; ')
}};

